<script>
  import{onMount}from'svelte';let cameras=[],draft=null,message='';const blank=()=>({name:'',username:'onvif',password:'',manufacturer:'X Platform',model:'RTSP Bridge',hq:'',lq:'',width:1920,height:1080,fps:25});async function api(options={}){const r=await fetch('/api/cameras',{headers:{'content-type':'application/json'},...options}),d=await r.json();if(!r.ok)throw Error(d.error);return d}async function load(){cameras=(await api()).cameras}async function save(){await api({method:draft.id?'PUT':'POST',body:JSON.stringify(draft)});draft=null;message='Camera saved. UniFi Protect can now discover it.';await load()}async function remove(c){if(confirm(`Delete ${c.name}?`)){await api({method:'DELETE',body:JSON.stringify({id:c.id})});await load()}}onMount(load);
</script>
<svelte:head><title>RTSP to ONVIF</title></svelte:head>
<header><div><span>X APPLICATION</span><h1>RTSP to ONVIF</h1><p>Present existing RTSP streams as virtual ONVIF cameras for UniFi Protect.</p></div><button class="primary" on:click={()=>draft=blank()}>Add camera</button></header>
<main>{#if message}<p class="notice">{message}</p>{/if}<section class="summary"><article><small>CAMERAS</small><b>{cameras.length}</b></article><article><small>DISCOVERY</small><b>WS-Discovery :3702</b></article><article><small>MODE</small><b>RTSP passthrough</b></article></section><section class="list"><div class="head"><h2>Virtual cameras</h2><p>Enable “Discover Third-Party Cameras” in UniFi Protect.</p></div>{#each cameras as camera}<article><div class="camera-icon">◉</div><div><h3>{camera.name}</h3><p>{camera.model} · {camera.width}×{camera.height} · {camera.fps} FPS</p><code>{camera.hq}</code>{#if camera.lq}<small>LQ configured</small>{/if}</div><div class="actions"><button on:click={()=>draft={...camera}}>Edit</button><button class="danger" on:click={()=>remove(camera)}>Delete</button></div></article>{:else}<div class="empty"><b>No virtual cameras yet</b><span>Add an RTSP stream to expose it through ONVIF.</span></div>{/each}</section></main>
{#if draft}<div class="backdrop" on:click={e=>e.currentTarget===e.target&&(draft=null)}><form on:submit|preventDefault={save}><header><div><span>CAMERA</span><h2>{draft.id?'Edit camera':'Add camera'}</h2></div><button type="button" on:click={()=>draft=null}>×</button></header><div class="grid"><label>Name<input bind:value={draft.name} required placeholder="Front door"></label><label>ONVIF username<input bind:value={draft.username} required></label><label>ONVIF password<input bind:value={draft.password} type="password" required></label><label>Manufacturer<input bind:value={draft.manufacturer}></label><label>Model<input bind:value={draft.model}></label><label>HQ RTSP URL<input bind:value={draft.hq} type="url" required placeholder="rtsp://user:pass@camera/high"></label><label>LQ RTSP URL <small>Optional</small><input bind:value={draft.lq} type="url" placeholder="rtsp://camera/low"></label><div class="three"><label>Width<input bind:value={draft.width} type="number" min="320"></label><label>Height<input bind:value={draft.height} type="number" min="240"></label><label>FPS<input bind:value={draft.fps} type="number" min="1" max="60"></label></div></div><button class="primary wide">Save camera</button></form></div>{/if}
<style>:global(*){box-sizing:border-box}:global(body){margin:0;background:#080c11;color:#eaf0f5;font:14px Inter,system-ui,sans-serif}header,main{width:min(1100px,calc(100% - 32px));margin:auto}body>header,header{display:flex;align-items:end;justify-content:space-between;gap:20px;padding:48px 0 28px}span,small{color:#8996a4}header span,.summary small{color:#da3;font-size:10px;font-weight:800;letter-spacing:.16em}h1{font-size:42px;margin:5px 0}h2,h3,p{margin-top:0}header p,.head p{color:#8e9aa7}.primary{border:0;background:#da3;color:#181405;font-weight:800}.primary,button,input{border-radius:8px;padding:10px 13px}button{cursor:pointer;border:1px solid #34404c;background:#18202a;color:white}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:24px}.summary article{display:grid;gap:8px;padding:17px;background:#10161e;border:1px solid #26313d;border-radius:10px}.summary b{font-size:18px}.list{padding:20px;background:#0d131a;border:1px solid #26313d;border-radius:13px}.head{display:flex;justify-content:space-between}.list>article{display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:15px;padding:15px 0;border-top:1px solid #222d38}.camera-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:12px;background:#2b2510;color:#da3;font-size:25px}.list h3{margin:0 0 5px}.list article p{margin:0 0 5px;color:#8e9aa7}.list code{display:block;max-width:600px;overflow:hidden;text-overflow:ellipsis;color:#b8c2cc}.actions{display:flex;gap:6px}.danger{color:#ff9ba5;border-color:#67333a}.empty{min-height:220px;display:grid;place-content:center;text-align:center;gap:8px;color:#8d99a6}.notice{padding:11px;border:1px solid #66581b;color:#da3;border-radius:8px}.backdrop{position:fixed;inset:0;display:grid;place-items:center;padding:20px;background:#000c;overflow:auto}.backdrop form{width:min(680px,100%);padding:22px;background:#10161e;border:1px solid #34404c;border-radius:14px}.backdrop form>header{width:100%;padding:0 0 18px}.backdrop h2{margin:4px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.grid label{display:grid;gap:6px;color:#aeb8c2}.grid label:nth-child(6),.grid label:nth-child(7),.three{grid-column:1/-1}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}input{width:100%;border:1px solid #34404c;background:#080d13;color:white}.wide{width:100%;margin-top:16px}@media(max-width:650px){header,.head{align-items:stretch;flex-direction:column}.summary,.grid{grid-template-columns:1fr}.grid>*{grid-column:auto!important}.list>article{grid-template-columns:42px 1fr}.actions{grid-column:1/-1}.three{grid-template-columns:1fr}}</style>
